const fs = require('fs');

const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/);
const N = parseInt(input[0], 10);
const S = input.slice(1).join('').slice(0, N);

function increment(s) {
    const arr = s.split('');
    let i = arr.length - 1;

    while (i >= 0 && arr[i] === '9') {
        arr[i] = '0';
        i--;
    }

    if (i < 0) {
        arr.unshift('1');
    } else {
        arr[i] = String.fromCharCode(arr[i].charCodeAt(0) + 1);
    }

    return arr.join('');
}

function valid(len) {
    let current = S.slice(0, len);
    let pos = len;

    while (pos < N) {
        current = increment(current);

        const curLen = current.length;
        if (pos + curLen > N) return false;

        for (let i = 0; i < curLen; i++) {
            if (current[i] !== S[pos + i]) return false;
        }

        pos += curLen;
    }

    return true;
}

let answer = '';

for (let len = 1; len <= N; len++) {
    if (S[0] === '0') break;

    if (valid(len)) {
        answer = S.slice(0, len);
        break;
    }
}

process.stdout.write(answer + '\n');
